import{z as s,x as p,o as l,c as i,q as o,j as B,D as e,d as t,s as n,S as r,b as E}from"./chunks/framework.C8m1ZpeB.js";const f=JSON.parse('{"title":"长输出场景的投机","description":"","frontmatter":{"title":"长输出场景的投机","date":"2026-09-18T00:00:00.000Z","section":"llm"},"headers":[],"relativePath":"llm/spec-longoutput.md","filePath":"llm/spec-longoutput.md","lastUpdated":1791063341000}'),m={name:"llm/spec-longoutput.md"};function d(h,a,D,g,u,C){const A=p("Mermaid");return l(),i("div",null,[a[2]||(a[2]=o('<h1 id="长输出场景的投机" tabindex="-1">长输出场景的投机 <a class="header-anchor" href="#长输出场景的投机" aria-label="Permalink to &quot;长输出场景的投机&quot;">​</a></h1><div class="epigraph"><p>输出越长，接受率的漂移越藏不住：开头是模板，中间是推理，结尾是收束——一条生成里住着好几种负载。</p><footer>—— 据 Leviathan et al., 2023 与 EAGLE 系列在代码与推理任务上的口径整理</footer></div><p><a href="/llm/spec-edge">上一课</a>把投机按到了资源最紧的设备上。系统交互单元的最后一课回到负载本身：长输出。代码生成、agent 连续工具调用、长思维链、文档起草，输出动辄数千 token。期望值上，投机的相对收益与总长无关——每轮省的比例是同一个；但长输出把两件被短输出掩盖的事放大：接受率沿输出位置的漂移，与完成时间分布的尾部。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>接受率不是全程常数。生成的开头常是模板与结构（import、函数签名、JSON 骨架），高度可猜，复制式草稿在这里近乎百发百中；中段是真正的推理与创作，\\(\\alpha\\) 掉下去；收尾又回到格式。一条 4000 token 的生成把这三段都经历一遍，全局平均 \\(\\alpha\\) 掩盖了「哪一段在赚、哪一段在赔」。第二个问题在尾部：单步加速比是期望，完成的墙钟是几千轮的累积；\\(\\tau\\) 的方差随轮数部分抵消，但「遇到低 \\(\\alpha\\) 长段」的坏情形直接决定 p99 完成时间。第三个问题与 <a href="/llm/kv-map">KV 管理</a>接上：长输出的 KV 本就贴预算，投机再叠加 \\(\\gamma\\) 个草稿位的峰值，抢占概率被放大。</p><p><span class="marginnote">数字实例：一条 4000 token 的代码生成，前 800 token 是 import 与函数骨架（\\(\\alpha\\approx 0.95\\)），后 3200 是推理（\\(\\alpha\\approx 0.5\\)）。全局平均 \\(\\alpha=(800\\times 0.95+3200\\times 0.5)/4000\\approx 0.59\\)——拿这个数调 \\(\\gamma\\)，会把开头最赚的段也一并收窄。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p><strong>按段换草稿</strong>。把在线选择的桶从「请求级」细化到「段级」：结构化与复制段（代码框架、schema、引用原文）用 n-gram/检索草稿；自由推理段换特征级草稿或收窄树；段边界由轻量分类或解码状态（刚进 fenced block、刚出引号）触发。<a href="/llm/constrained-decoding">约束段</a>里的结构由文法保证，草稿只需猜槽位内容。<strong>沿位置调 \\(\\gamma\\)</strong>。<a href="/llm/acceptance-length-sched">接受长度调度</a>的逐请求 \\(\\gamma\\) 在长输出上按输出位置重估：开头模板段可以放宽 \\(\\gamma\\)，进入推理段收窄。<strong>盯住尾部</strong>。SLO 对长输出应写完成时间分位数而非单步 TPOT；监控按输出位置分桶报 \\(\\alpha\\)，漂移一眼可见。</p>',8)),(l(),B(r,null,{default:e(()=>[n(A,{id:"mermaid-22",class:"mermaid",graph:"flowchart%20TD%0A%20%20GEN%5B%22%E7%94%9F%E6%88%90%E5%88%86%E6%AE%B5%E7%9B%91%E6%8E%A7%22%5D%20--%3E%20SEG%7B%22%E5%BD%93%E5%89%8D%E6%AE%B5%E7%B1%BB%E5%9E%8B%22%7D%0A%20%20SEG%20--%3E%7C%22%E6%A8%A1%E6%9D%BF%20%2F%20%E7%BB%93%E6%9E%84%20%2F%20%E5%A4%8D%E5%88%B6%22%7C%20HI%5B%22n-gram%20%E8%8D%89%E7%A8%BF%20%2B%20%E5%A4%A7%20%CE%B3%22%5D%0A%20%20SEG%20--%3E%7C%22%E8%87%AA%E7%94%B1%E6%8E%A8%E7%90%86%22%7C%20MID%5B%22%E7%89%B9%E5%BE%81%E7%BA%A7%E8%8D%89%E7%A8%BF%20%2B%20%E6%94%B6%E7%AA%84%E6%A0%91%22%5D%0A%20%20SEG%20--%3E%7C%22%E6%A0%BC%E5%BC%8F%E6%94%B6%E6%9D%9F%22%7C%20HI2%5B%22%E7%BB%93%E6%9E%84%E5%8F%AF%E7%8C%9C%EF%BC%8C%E6%81%A2%E5%A4%8D%20%CE%B3%22%5D%0A%20%20HI%20--%3E%20TAU%5B%22%E6%8C%89%E6%8E%A5%E5%8F%97%E9%95%BF%E5%BA%A6%E6%8F%90%E4%BA%A4%22%5D%0A%20%20MID%20--%3E%20TAU%0A%20%20HI2%20--%3E%20TAU%0A%20%20TAU%20--%3E%20WATCH%5B%22%E6%8C%89%E4%BD%8D%E7%BD%AE%E5%88%86%E6%A1%B6%E8%AE%B0%E5%BD%95%20%CE%B1%22%5D%0A%20%20WATCH%20--%3E%20GEN%0A"})]),fallback:e(()=>[...a[0]||(a[0]=[t(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=E("h2",{id:"机制",tabindex:"-1"},[t("机制 "),E("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),a[4]||(a[4]=E("p",null,"长输出放大漂移的机制在条件概率链上：\\(\\alpha_t\\) 是前缀的函数，而前缀由自己的生成历史构成。开局走偏，中段的分布整体移动，草稿在「目标的习惯」上训练，偏出习惯区后接受率进一步下滑——漂移有自我放大的成分。这解释了一个反直觉现象：长输出上的实测加速比常低于短输出基准，不是投机变差，而是可猜段的占比变了。机制上对应的做法不是调大 \\(\\gamma\\) 硬扛，而是让提议形状跟着条件分布走：复制式草稿赌「输出会重复已见文本」，特征级草稿赌「局部规律可外推」，两边的赌注押在不同段位上，分段切换就是把赌注对齐。复制式草稿的机制还有一条免费红利：抄写段（总结引用原文、改写保留片段）的草稿与目标分布天然重合，\\(\\alpha\\) 接近 1，一轮前进接近 \\(\\gamma+1\\)，这是学习型草稿在推理段拿不到的深度。",-1)),a[5]||(a[5]=E("p",null,[E("span",{class:"marginnote"},"把「全局平均 \\(\\alpha\\)」换成「按输出位置分桶的 \\(\\alpha\\) 曲线」，很多谜团直接解开：加速比缩水往往对应位置 1000 之后的一段低谷，而不是草稿整体变差。看板上有这条曲线，才能定位是换草稿、收 \\(\\gamma\\) 还是随它去。")],-1)),a[6]||(a[6]=E("p",null,[E("span",{class:"marginnote"},"直觉类比：草稿像一个熟读目标模型文风的代笔。开局走偏等于作家突然换了口音，代笔越写越吃力（\\(\\alpha\\) 下滑），写出来的东西又进一步带偏下文——「口音漂移」就这样自己强化自己。")],-1)),(l(),B(r,null,{default:e(()=>[n(A,{id:"mermaid-35",class:"mermaid",graph:"flowchart%20TD%0A%20%20S%5B%22%E5%BC%80%E5%B1%80%E8%B5%B0%E5%81%8F%3A%20%E9%87%87%E6%A0%B7%E8%90%BD%E5%9C%A8%E4%B9%A0%E6%83%AF%E5%8C%BA%E5%A4%96%22%5D%20--%3E%20P%5B%22%E5%89%8D%E7%BC%80%E5%88%86%E5%B8%83%E6%95%B4%E4%BD%93%E7%A7%BB%E5%8A%A8%22%5D%0A%20%20P%20--%3E%20D%5B%22%E8%8D%89%E7%A8%BF%E5%81%8F%E5%87%BA%E8%AE%AD%E7%BB%83%E6%97%B6%E8%A7%81%E8%BF%87%E7%9A%84%E6%A8%A1%E5%BC%8F%22%5D%0A%20%20D%20--%3E%20A%5B%22%E6%8E%A5%E5%8F%97%E7%8E%87%20%CE%B1%20%E8%BF%9B%E4%B8%80%E6%AD%A5%E4%B8%8B%E6%BB%91%22%5D%0A%20%20A%20--%3E%20W%5B%22%E4%BF%AE%E6%AD%A3%20token%20%E5%8D%A0%E6%AF%94%E5%8D%87%E9%AB%98%2C%20%E6%96%87%E9%A3%8E%E7%BB%A7%E7%BB%AD%E5%81%8F%E7%A6%BB%22%5D%0A%20%20W%20--%3E%7C%22%E5%8F%8D%E9%A6%88%E5%9B%9E%E5%89%8D%E7%BC%80%22%7C%20P%0A"})]),fallback:e(()=>[...a[1]||(a[1]=[t(" Loading... ",-1)])]),_:1})),a[7]||(a[7]=o('<h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>分段切换的触发器本身会错：误判「推理段」为「复制段」，草稿高频拒绝白烧前向；误判方向相反则放着高 \\(\\alpha\\) 不赚。触发器要按误判成本定阈值。检索式草稿依赖可抄的素材，闭卷创作段无从抄起，硬上只会降速。长思维链是特例：自我重复的风格让草稿容易拿分，速度赚了，但内容退化（绕圈、复读）与投机无关——无损只保证分布与目标一致，目标自己会退化，别把账算在投机头上。最后，长输出的验收必须连质量指标一起报：数千 token 上的累积截断、停止条件与草稿假命中（见<a href="/llm/stop-sequences">停用词与 stop sequences</a>）都会在长尾处显形。</p><p><span class="marginnote">常见误区：看到长思维链上速度赚了，就默认内容也没问题。无损只保证投机输出与目标模型同分布——目标自己绕圈复读时，投机只是更快地绕圈。速度账与质量账必须分开结。</span></p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>长输出把接受率漂移与完成时间尾部放大：全局平均 \\(\\alpha\\) 掩盖段位差异。</li><li>按段换草稿：复制段用 n-gram/检索，推理段用特征级并收窄树，段级桶替代请求级桶。</li><li>\\(\\gamma\\) 沿输出位置调度；模板段放宽、推理段收窄。</li><li>漂移有自我放大成分：开局走偏会移动中段分布，实测加速比缩水先查位置分桶曲线。</li><li>验收看完成时间分位数与质量指标；无损不豁免目标自身的退化。</li><li>出处：Leviathan et al., ICML 2023；Li et al., <em>EAGLE</em> 系列，2024–2025；据本仓库投机课序整理。</li></ul>',5))])}const F=s(m,[["render",d]]);export{f as __pageData,F as default};
